/**
 * Pages generated by `generate-from-files` in the current build: output path → template and source file.
 * Used to point diagnostics to the template, and by `yassb inspect`.
 *
 * @internal
 */
export interface GeneratedPage {
  template: string;
  source: string;
}

/**
 * @internal
 */
export const GENERATED_PAGES = new Map<string, GeneratedPage>();

/**
 * @internal
 */
export function clearGeneratedPages(): void {
  GENERATED_PAGES.clear();
}
